#!/usr/bin/env node
/**
 * snap-restore/bench.js
 *
 * Demo: "hibernate" a tab vs killing it and doing a full reload.
 *
 * This runs inside Puppeteer — a Node tool famous for being slow — and shows
 * exactly why the tab-caching optimization matters: today, getting a tab back
 * means a full reload that redoes network + parse + JS execution and loses all
 * page state. A snapshot restore skips that work and keeps the state.
 *
 *  1. Load a heavy fixture (12,000-row grid generated by JS)
 *  2. Interact: scroll, fill the form, mutate JS runtime state
 *  3. Snapshot: rendered DOM (scripts stripped) + scroll + form values + JS state
 *  4. Benchmark two ways of "getting the tab back":
 *       A) full reload  -> network + reparse + re-execute (state LOST)
 *       B) restore      -> new tab, replay snapshot       (state PRESERVED)
 *
 * Run: npm install puppeteer && node snap-restore/bench.js
 */
'use strict';

const http = require('http');
const fs = require('fs');
const path = require('path');
const puppeteer = require('puppeteer');

const FIXTURE = fs.readFileSync(path.join(__dirname, 'fixture.html'), 'utf8');

// ---------------------------------------------------------------- tiny server
// Serving over HTTP gives a full reload a real (if local) network cost.
const server = http.createServer((req, res) => {
  if (req.url === '/fixture') {
    res.writeHead(200, { 'Content-Type': 'text/html' });
    res.end(FIXTURE);
  } else {
    res.writeHead(404);
    res.end();
  }
});
const listen = () =>
  new Promise((r) => server.listen(0, '127.0.0.1', () => r(server.address().port)));
const shutdown = () => new Promise((r) => server.close(r));

const mb = (n) => (n / 1048576).toFixed(2) + ' MB';

// ---------------------------------------------------------------- snapshot
// Capture the "render state" of a live tab. This is the analog of what a
// freeze-dried tab / bfcache-style serialization would persist: the rendered
// DOM (scripts stripped — we replay state, we don't re-execute), scroll
// position, form values, and shallow JS runtime state.
async function snapshot(page) {
  return page.evaluate(() => {
    const html = document.documentElement.outerHTML.replace(
      /<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi,
      ''
    );

    const forms = [...document.querySelectorAll('input, textarea, select')].map((el) => ({
      selector: uniqueSelector(el),
      tag: el.tagName,
      type: el.type || '',
      value: el.value,
      checked: el.checked,
      selectedIndex: el.selectedIndex,
    }));

    function uniqueSelector(el) {
      if (el.id) return '#' + CSS.escape(el.id);
      const parts = [];
      let node = el;
      while (node && node.nodeType === 1 && parts.length < 4) {
        let part = node.tagName.toLowerCase();
        if (node.id) {
          part = '#' + CSS.escape(node.id);
          parts.unshift(part);
          break;
        }
        const siblings = [...node.parentNode.children].filter(
          (s) => s.tagName === node.tagName
        );
        if (siblings.length > 1) part += ':nth-of-type(' + (siblings.indexOf(node) + 1) + ')';
        parts.unshift(part);
        node = node.parentNode;
      }
      return parts.join(' > ');
    }

    return {
      html,
      forms,
      scrollX: window.scrollX,
      scrollY: window.scrollY,
      demoState: window.__demoState,
      nodeCount: document.querySelectorAll('*').length,
      bytes: html.length,
    };
  });
}

// ---------------------------------------------------------------- restore
// New tab, replay the snapshot. No network, no script re-execution — the DOM
// comes straight from the snapshot and state is re-applied on top.
async function restore(page, snap) {
  await page.setContent(snap.html, { waitUntil: 'load' });
  await page.evaluate((s) => {
    window.scrollTo(s.scrollX, s.scrollY);
    for (const f of s.forms) {
      const el = document.querySelector(f.selector);
      if (!el) continue;
      if (f.tag === 'SELECT') el.selectedIndex = f.selectedIndex;
      else if (f.type === 'checkbox' || f.type === 'radio') el.checked = f.checked;
      else el.value = f.value;
    }
    window.__demoState = s.demoState;
  }, snap);
}

// ---------------------------------------------------------------- full reload
async function fullReload(browser, url) {
  const page = await browser.newPage();
  const t0 = performance.now();
  await page.goto(url, { waitUntil: 'networkidle0' });
  const ms = performance.now() - t0;
  const state = await page.evaluate(() => ({
    demoState: window.__demoState,
    scrollY: window.scrollY,
    name: document.querySelector('#name') ? document.querySelector('#name').value : null,
  }));
  return { page, ms, state };
}

// ---------------------------------------------------------------- interact
async function interact(page) {
  await page.evaluate(() => {
    // mutate JS runtime state (what a user actually does: change things)
    window.__demoState = {
      visits: 99,
      token: 'mutated-by-user',
      payloadLength: window.__demoState.payloadLength,
    };
    // fill the form
    document.querySelector('#name').value = 'hibernated-user';
    document.querySelector('#opt-in').checked = true;
    // scroll deep into the grid
    window.scrollTo(0, 4000);
  });
}

const heap = async (page) => (await page.metrics()).JSHeapUsedSize;

// Prefer a system Chromium (no download needed, matches a real user's browser);
// fall back to Puppeteer's bundled Chrome, then chrome-headless-shell.
const CHROME_PATHS = ['/usr/bin/chromium', '/usr/bin/google-chrome', '/usr/bin/chromium-browser'];
const findSystemChrome = () => CHROME_PATHS.find((p) => fs.existsSync(p));

async function launch() {
  const exe = findSystemChrome();
  if (exe) return puppeteer.launch({ headless: true, executablePath: exe });
  try {
    return await puppeteer.launch({ headless: true });
  } catch (err) {
    console.warn('bundled chrome unavailable, falling back to chrome-headless-shell:', err.message.split('\n')[0]);
    return puppeteer.launch({ headless: 'shell' });
  }
}

// ---------------------------------------------------------------- main
async function main() {
  const port = await listen();
  const url = `http://127.0.0.1:${port}/fixture`;

  const browser = await launch();
  try {
    // --- live tab: load, interact, snapshot ---
    const live = await browser.newPage();
    await live.goto(url, { waitUntil: 'networkidle0' });
    await interact(live);
    const snap = await snapshot(live);
    const liveHeap = await heap(live);
    await live.close();

    // --- A: full reload ---
    const a = await fullReload(browser, url);
    const reloadHeap = await heap(a.page);
    await a.page.close();

    // --- B: snapshot restore ---
    const b = await browser.newPage();
    const t0 = performance.now();
    await restore(b, snap);
    const restoreMs = performance.now() - t0;
    const restored = await b.evaluate(() => ({
      demoState: window.__demoState,
      scrollY: window.scrollY,
      name: document.querySelector('#name') ? document.querySelector('#name').value : null,
      nodeCount: document.querySelectorAll('*').length,
    }));
    const restoreHeap = await heap(b);
    await b.close();

    // --- report ---
    const stateOK =
      JSON.stringify(a.state.demoState) !== JSON.stringify(restored.demoState);
    console.log('snapshot size      :', (snap.bytes / 1024).toFixed(1) + ' KiB',
      `(${snap.nodeCount} DOM nodes preserved)`);
    console.log('');
    console.log(
      'metric             | full reload        | snapshot restore   '
    );
    console.log(
      '--------------------+--------------------+--------------------'
    );
    const row = (label, v1, v2) =>
      console.log(label.padEnd(20) + '| ' + String(v1).padEnd(18) + '| ' + String(v2).padEnd(18));
    row('tab back in', (a.ms / 1000).toFixed(2) + 's', (restoreMs / 1000).toFixed(2) + 's');
    row('JS heap (settled)', mb(reloadHeap), mb(restoreHeap));
    row('scroll position', a.state.scrollY + 'px', restored.scrollY + 'px');
    row('form value (#name)', JSON.stringify(a.state.name), JSON.stringify(restored.name));
    row('JS runtime state', JSON.stringify(a.state.demoState), JSON.stringify(restored.demoState));
    console.log('');

    const speedup = (a.ms / restoreMs).toFixed(1) + 'x faster';
    console.log(
      `verdict: full reload ${stateOK ? 'LOST' : 'kept'} the JS state; ` +
      `restore kept it and was ${speedup} (${(a.ms / 1000).toFixed(2)}s vs ` +
      `${(restoreMs / 1000).toFixed(2)}s). Live heap was ${mb(liveHeap)} — ` +
      `restore settles at ${mb(restoreHeap)}, close to live, without paying ` +
      `the reload cost.`
    );
    console.log(
      'Note: this is a shallow snapshot (DOM + form + scroll + top-level state). ' +
      'Closures, WebSockets, GPU textures — the hard 90% — are not captured; ' +
      'that is the real engineering gap freeze-dried tabs are working on.'
    );
  } finally {
    await browser.close();
    await shutdown();
  }
}

main().catch((err) => {
  console.error('bench failed:', err.message);
  process.exit(1);
});
